definition.script:
pipeline{
    agent{
        label "ansible"
    }
    stages{
        stage("Set up a credential to an environment variable") {
            steps{
                script{
                    echo "### START: setting up a credential to an environment variable"
                    withCredentials([
                        usernamePassword(
                            credentialsId: "artifactory-app-credential",
                            usernameVariable: "ARTIFACTORY_USERNAME",
                            passwordVariable: "ARTIFACTORY_PASSWORD")
                    ]){
                        try{
                            env.ARTIFACTORY_USERNAME = "${ARTIFACTORY_USERNAME}"
                            env.ARTIFACTORY_PASSWORD = "${ARTIFACTORY_PASSWORD}"
                        } catch(Exception e){
                            error "setting up a credential failed: ${e.message}"
                        }
                    }
                }
            }
        }
        stage("Run Ansible Playbook on Ansible Agent to webapi") {
            steps{
                echo "### START: running ansible playbook for grafana environment on ansible node to webapi"
                sh "ansible-playbook -i /root/ansible/playbook/inventory_webapi.ini /root/ansible/playbook/deploy_webapi-artf-with-grafana.yml"
            }
        }
        stage("Run Ansible Playbook on Ansible Agent to webui") {
            steps{
                echo "### START: running ansible playbook for grafana environment on ansible node to webui"
                sh "ansible-playbook -i /root/ansible/playbook/inventory_webui.ini /root/ansible/playbook/deploy_webui-artf-with-grafana.yml"
            }
        }
    }
    post{
        always{
            echo "========always========"
        }
        success{
            echo "========pipeline executed successfully ========"
        }
        failure{
            echo "========pipeline execution failed========"
        }
    }
}
